interface Button { render(): void }
interface Checkbox { toggle(): void }
interface UIFactory { createButton(): Button; createCheckbox(): Checkbox }
class MacButton implements Button { render(){ /* mac rendering */ } }
class MacCheckbox implements Checkbox { toggle(){ /* mac toggle */ } }
class MacFactory implements UIFactory { createButton(){ return new MacButton() } createCheckbox(){ return new MacCheckbox() } }

interface Button {}
class WinButton implements Button {}
class MacButton implements Button {}
function createButton(platform: string): Button {
  switch(platform) {
    case 'win': return new WinButton()
    case 'mac': return new MacButton()
  }
  throw new Error('Unknown platform')
}

